{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Inogatran, structurally close to the query with a basic guanidine, cyclohexylglycine, and carboxylate, showed <5% oral bioavailability in healthy volunteers, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "DX-9065a, a benzamidine-containing factor Xa inhibitor, had only 2–3% human oral bioavailability attributed to its strong basic amidino groups; the query contains a free benzamidine, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Melagatran, a peptidomimetic with basic amidine/guanidine and carboxylate functionalities, had 3–7% oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Avoralstat, an oral kallikrein inhibitor containing a benzamidine and carboxylic acid, had low oral bioavailability in humans, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "AZD0837 showed 22–55% human oral bioavailability, but it is a methoxyamidine prodrug with the basic amidine masked; this high-F evidence is only weakly transferable to the free-amidine query and does not outweigh the low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a free benzamidine-containing peptidomimetic with a carboxylic acid and multiple hydrogen-bond donors, closely resembling inogatran, DX-9065a, and melagatran, all of which show low (<10%) human oral bioavailability. The only high-F analogue is a prodrug with a masked amidine, which does not apply to the free amidine query. Therefore the query is predicted to have F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement is available for the query molecule.",
    "The high-F AZD0837 evidence is for a prodrug form, not the free amidine present in the query.",
    "No permeability, transporter, or solubility data specific to the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

